try{chdir(__DIR__);require 'vendor/autoload.php';$app=require 'bootstrap/app.php';$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();$m=config('ccs_customer_email.mailer','smtp');echo 'OTP enabled: '.(config('ccs_customer_email.enabled')?'yes':'no')."\nMailer: ".$m."\nTransport: ".config('mail.mailers.'.$m.'.transport')."\nSMTP host: ".config('mail.mailers.'.$m.'.host')."\nFrom: ".config('mail.from.address')."\n";echo 'OTP table: '.(Illuminate\Support\Facades\Schema::hasTable('ccs_customer_email_otps')?'present':'MISSING')."\n";foreach($argv as $arg)if(str_starts_with($arg,'--send=')){$to=substr($arg,7);if(!filter_var($to,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Use --send=your-own-email@example.com');if(config('mail.mailers.'.$m.'.transport')!=='smtp')throw new RuntimeException('A real SMTP mailer is required.');Illuminate\Support\Facades\Mail::mailer($m)->raw('CCS Solutions SMTP delivery test. No customer data or sign-in code is included.',fn($mail)=>$mail->to($to)->subject('CCS Solutions email delivery test'));echo "SMTP accepted the test message. Check your inbox/spam to confirm actual delivery.\n";}echo 'Customer email login ready: '.(app(App\Services\CcsCustomerEmailOtp::class)->ready()?'yes (still confirm mailbox delivery)':'no — configure SMTP and enable the OTP flag')."\n";}catch(Throwable $e){fwrite(STDERR,'Email check failed ('.get_class($e)."). Check private SMTP settings; no passwords are printed.\n");exit(1);}
